import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"超时模式（Timeout）","description":"","frontmatter":{},"headers":[],"relativePath":"evolution/timeout.md","filePath":"evolution/timeout.md","lastUpdated":0}`),a={name:`evolution/timeout.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="超时模式-timeout" tabindex="-1">超时模式（Timeout） <a class="header-anchor" href="#超时模式-timeout" aria-label="Permalink to “超时模式（Timeout）”">​</a></h1><p>超时给每次跨进程调用设一个时间上限，到点就放弃这次调用，走降级或明确报错，不让调用方无限等下去。它出自 Nygard 的《Release It!》[S12]，要解决的问题不是&quot;下游报错&quot;，而是&quot;下游不响应&quot;：没有超时的调用一旦碰上挂起的下游（死循环、长时间 GC、网络丢包后的 TCP 重传），调用方的线程或协程就永远占着，资源一格一格被吃光，最后整个服务不可用。Nygard 的原话是所有跨进程调用都要设超时，无一例外——<a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>统计失败率，超时负责把&quot;慢&quot;先变成&quot;失败&quot;，没有超时的失败率统计是残缺的，挂着的调用根本不计入。</p><h2 id="两类超时与总预算" tabindex="-1">两类超时与总预算 <a class="header-anchor" href="#两类超时与总预算" aria-label="Permalink to “两类超时与总预算”">​</a></h2><p>一次跨进程调用至少有两个独立的时限：</p><ul><li><strong>连接超时</strong>：建立 TCP 连接的等待上限。目标地址不可达时，操作系统默认要等很久，这个值一般几百毫秒到一秒。</li><li><strong>读超时（响应超时）</strong>：连接建立后等响应的时长，按下游正常 P99 延迟的 1.5–2 倍设，不是拍一个&quot;感觉差不多&quot;的数。</li></ul><p>多层调用还要有<strong>总预算</strong>：一次用户请求串起网关、服务 A、数据库，各段超时不能简单相加——每段的超时要小于上游传下来的剩余预算。gRPC 的 deadline 传播就是为此设计的：上游把剩余时间随请求传给下游，下游取 min(本地配置, 上游剩余) 作为自己的上限。</p><h2 id="适用与不适用" tabindex="-1">适用与不适用 <a class="header-anchor" href="#适用与不适用" aria-label="Permalink to “适用与不适用”">​</a></h2><p>适用于一切跨进程调用：HTTP、RPC、数据库、缓存、消息队列。判断依据只有一条——调用会占用一份进程外资源（连接、内存、线程等待位），就要有时限。</p><p>不适用的只有进程内调用：本地函数不占连接，加超时的复杂度不值得。两种常见的错误用法要避开：</p><ol><li><strong>把超时当重试的替代品</strong>：超时只负责止损，恢复要靠<a href="/hello-design-patterns/evolution/retry">重试</a>，两者是配合关系。</li><li><strong>超时设得比下游 P99 还短</strong>：正常慢请求被杀掉，下游的副作用却已经发生——调用方当失败处理，下游实际执行成功，数据从此不一致。</li></ol><h2 id="与其他模式的关系" tabindex="-1">与其他模式的关系 <a class="header-anchor" href="#与其他模式的关系" aria-label="Permalink to “与其他模式的关系”">​</a></h2><ul><li>与<a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>：超时把慢调用转成失败，熔断器统计这些失败决定断不断闸。顺序固定：先有超时，熔断器的窗口才有完整的失败样本。</li><li>与<a href="/hello-design-patterns/evolution/retry">重试</a>：单次超时 × (重试次数 + 1) 是总时长上限，必须留在调用方自己的预算内；写操作超时后重试前先确认副作用没发生。</li><li>与<a href="/hello-design-patterns/evolution/bulkhead">隔舱</a>：超时管单次调用的时长，隔舱管同时在飞的调用数量，两者一起决定最坏情况下一个慢下游吃掉多少资源。</li><li>超时后的降级写法与<a href="/hello-design-patterns/behavioral/strategy">策略</a>一致：正常实现和兜底实现是两个可替换的策略。</li></ul><h2 id="关键参数" tabindex="-1">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to “关键参数”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>取值依据</th><th>设错的后果</th></tr></thead><tbody><tr><td>连接超时</td><td>几百毫秒到 1 秒，跨公网适当放宽</td><td>太短把正常建连杀掉；太长对不可达地址形成长时间占用</td></tr><tr><td>读超时</td><td>下游 P99 的 1.5–2 倍</td><td>比 P99 短，副作用已发生却被当失败；太长，线程占用时间跟着变长</td></tr><tr><td>总预算</td><td>产品的响应时间要求</td><td>各段超时之和大于总预算，用户已经超时，下游却全&quot;成功&quot;</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>Go 实现：连接超时放在 Transport 的拨号器上，读超时用 <code>context.WithTimeout</code> 控制，并且沿用上游传下来的 deadline——上游预算更紧时取更小值。</p><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">package</span><span style="color:#B392F0;"> client</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> (</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">context</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">net</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">net/http</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">time</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">var</span><span style="color:#E1E4E8;"> httpClient </span><span style="color:#F97583;">=</span><span style="color:#F97583;"> &amp;</span><span style="color:#B392F0;">http</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">Client</span><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#818e99;">	// 连接超时归 Transport：拨号上限 500ms</span></span>
<span class="line"><span style="color:#E1E4E8;">	Transport: </span><span style="color:#F97583;">&amp;</span><span style="color:#B392F0;">http</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">Transport</span><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#E1E4E8;">		DialContext: (</span><span style="color:#F97583;">&amp;</span><span style="color:#B392F0;">net</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">Dialer</span><span style="color:#E1E4E8;">{Timeout: </span><span style="color:#79B8FF;">500</span><span style="color:#F97583;"> *</span><span style="color:#E1E4E8;"> time.Millisecond}).DialContext,</span></span>
<span class="line"><span style="color:#E1E4E8;">	},</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// Query 请求 url，读超时按下游 P99 的两倍设，并沿用上游的 deadline</span></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#B392F0;"> Query</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">ctx</span><span style="color:#B392F0;"> context</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">Context</span><span style="color:#E1E4E8;">, </span><span style="color:#FFAB70;">url</span><span style="color:#F97583;"> string</span><span style="color:#E1E4E8;">) (</span><span style="color:#F97583;">*</span><span style="color:#B392F0;">http</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">Response</span><span style="color:#E1E4E8;">, </span><span style="color:#F97583;">error</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#E1E4E8;">	local </span><span style="color:#F97583;">:=</span><span style="color:#79B8FF;"> 2</span><span style="color:#F97583;"> *</span><span style="color:#E1E4E8;"> time.Second</span></span>
<span class="line"><span style="color:#F97583;">	if</span><span style="color:#E1E4E8;"> deadline, ok </span><span style="color:#F97583;">:=</span><span style="color:#E1E4E8;"> ctx.</span><span style="color:#B392F0;">Deadline</span><span style="color:#E1E4E8;">(); ok {</span></span>
<span class="line"><span style="color:#F97583;">		if</span><span style="color:#E1E4E8;"> d </span><span style="color:#F97583;">:=</span><span style="color:#E1E4E8;"> time.</span><span style="color:#B392F0;">Until</span><span style="color:#E1E4E8;">(deadline); d </span><span style="color:#F97583;">&lt;</span><span style="color:#E1E4E8;"> local {</span></span>
<span class="line"><span style="color:#E1E4E8;">			local </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> d </span><span style="color:#818e99;">// 上游预算更紧时取更小值</span></span>
<span class="line"><span style="color:#E1E4E8;">		}</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#E1E4E8;">	ctx, cancel </span><span style="color:#F97583;">:=</span><span style="color:#E1E4E8;"> context.</span><span style="color:#B392F0;">WithTimeout</span><span style="color:#E1E4E8;">(ctx, local)</span></span>
<span class="line"><span style="color:#F97583;">	defer</span><span style="color:#B392F0;"> cancel</span><span style="color:#E1E4E8;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E1E4E8;">	req, err </span><span style="color:#F97583;">:=</span><span style="color:#E1E4E8;"> http.</span><span style="color:#B392F0;">NewRequestWithContext</span><span style="color:#E1E4E8;">(ctx, http.MethodGet, url, </span><span style="color:#79B8FF;">nil</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"><span style="color:#F97583;">	if</span><span style="color:#E1E4E8;"> err </span><span style="color:#F97583;">!=</span><span style="color:#79B8FF;"> nil</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">		return</span><span style="color:#79B8FF;"> nil</span><span style="color:#E1E4E8;">, err</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#F97583;">	return</span><span style="color:#E1E4E8;"> httpClient.</span><span style="color:#B392F0;">Do</span><span style="color:#E1E4E8;">(req)</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><p>Java 侧不必自己写：Resilience4j 的 <code>TimeLimiter</code>（<code>timeoutDuration</code>）、gRPC 的 <code>Context.withDeadlineAfter</code>、<code>java.net.http.HttpRequest</code> 的 <code>timeout</code> 都是同一个模型；Spring 的事务超时（<code>@Transactional(timeout=…)</code>）管的是数据库那一段。</p><h2 id="接入时的三件小事" tabindex="-1">接入时的三件小事 <a class="header-anchor" href="#接入时的三件小事" aria-label="Permalink to “接入时的三件小事”">​</a></h2><ol><li><strong>超时要有去处</strong>：到点之后返回什么（缓存值、默认值、明确报错）要提前定好，不能到点再想。</li><li><strong>链路上越靠外的预算越大</strong>：下游配置的超时要小于上游的剩余预算，否则上游已放弃、下游还在干，下游的活白做。</li><li><strong>超时不等于失败</strong>：写操作超时后副作用可能已经发生，直接重试可能重复扣款——先确认结果（幂等键或查询）再决定下一步。</li></ol><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>、<a href="/hello-design-patterns/evolution/bulkhead">隔舱</a>、<a href="/hello-design-patterns/evolution/retry">重试</a>：同出 Release It! 的稳定性三模式。</li><li><a href="/hello-design-patterns/behavioral/strategy">策略模式</a>：超时后降级实现的切换。</li><li><a href="/hello-design-patterns/evolution/overview">现代演进导读</a>：本篇为什么放在 GoF 之后。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S12] Michael T. Nygard，《Release It!》第 2 版，Pragmatic Bookshelf，2018。超时的原始出处。</li><li>[S13] Chris Richardson，《Microservices Patterns》，2018，超时与 deadline 传播的实践口径。</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};